"use strict";(globalThis.webpackChunkgrc||=[]).push([[31562],{33623(e){e.exports=JSON.parse('{"citeKey":"byna2006memoryservers","slug":"byna-2006-memory-servers-035f","title":"Memory Servers: A Scope of SOA for High-End Computing","authors":["S. Byna","X.-H. Sun","R. Nakhoul"],"venue":"The IEEE Service Computing Conference (SCC) 2006, Chicago","type":"Conference","entryType":"inproceedings","date":"September, 2006","year":2006,"era":"iit","month":9,"doi":"10.1109/scc.2006.67","abstract":"The expanding gap between microprocessor and disk performance has initiated new techniques of providing memory as a service in high-end computing (HEC). Although the processor and disk densities have improved over the last decades, the improvement of disk performance is inferior to that of processors, which is causing a bottleneck for HEC. With the rapid growth of network technology for cluster computers, the idea of accessing memory of an idle peer node has proven to be faster than accessing a disk. With this motivation, many researchers developed systems that offer idle memory as a service. In this paper, we present a brief survey of various systems that offer memory service in improving the disk access performance and discuss the scope of applying service oriented architecture (SOA) for HEC.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2006/byna-2006-memory-servers-035f.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":[],"memberAuthors":["byna-surendra","sun-xian-he"]}')}}]);